16	// The nozzle and the loaded spools, as the device last reported them. The
17	// plate is not among them: MachineObject carries no build-plate type.
18	void read_reported_hardware(MachineObject& machine, DiscoveredPrinter& printer)
19	{
20	    if (const DevExtderSystem* extruders = machine.GetExtderSystem()) {
21	        printer.nozzle_diameter = extruders->GetNozzleDiameter(0);
22	        if (extruders->GetTotalExtderCount() > 0 && machine.is_connected())
23	            printer.nozzle_temperature = extruders->GetNozzleTempCurrent(0);
24	    }
25	    if (DevBed* bed = machine.GetBed(); bed != nullptr && machine.is_connected())
26	        printer.bed_temperature = bed->GetBedTemp();
27	    if (machine.is_in_printing()) {
28	        printer.progress_percent = machine.mc_print_percent;
29	        printer.job              = machine.subtask_name;
30	    }
31	    DevFilaSystem* filaments = machine.GetFilaSystem();
32	    if (!filaments) return;
33	    for (const auto& [ams_id, ams] : filaments->GetAmsList()) {
34	        if (!ams) continue;
35	        if (printer.ams_name.empty())
36	            printer.ams_name = ams->GetAmsType() == DevAms::AMS_LITE ? "AMS lite" : "AMS";
37	        for (const auto& [tray_id, tray] : ams->GetTrays()) {
38	            if (!tray || !tray->is_exists) continue;
39	            const std::string material = tray->sub_brands.empty() ? tray->get_display_filament_type() : tray->sub_brands;
40	            if (material.empty()) continue;
41	            printer.spools.push_back({(tray->is_bbl ? "Bambu " : "") + material,
42	                                      std::string(tray->get_color().GetAsString(wxC2S_HTML_SYNTAX).ToUTF8()),
43	                                      tray->get_display_filament_type()});
44	        }
45	    }
46	    // The external spool holder, which a printer without an AMS feeds from.
47	    for (const DevAmsTray& tray : machine.vt_slot) {
48	        if (!tray.is_exists || tray.get_display_filament_type().empty()) continue;
49	        const std::string material = tray.sub_brands.empty() ? tray.get_display_filament_type() : tray.sub_brands;
50	        printer.spools.push_back({(tray.is_bbl ? "Bambu " : "") + material,
51	                                  std::string(tray.get_color().GetAsString(wxC2S_HTML_SYNTAX).ToUTF8()),
52	                                  tray.get_display_filament_type()});
53	    }
54	}
