58	std::vector<DiscoveredPrinter> discover_printers(bool include_unreachable)
59	{
60	    std::vector<DiscoveredPrinter> result;
61	    DeviceManager* devices = wxGetApp().getDeviceManager();
62	    if (!devices) return result;
63	    const MachineObject* selected = devices->get_selected_machine();
64	    for (const auto& [id, machine] : devices->get_my_machine_list()) {
65	        if (!machine) continue;
66	        const bool reachable = machine->is_online() || machine->is_connected();
67	        if (!reachable && !include_unreachable) continue;
68	        DiscoveredPrinter printer{id, machine->get_dev_name(), machine->get_dev_ip(), machine->printer_type,
69	                                  machine->connection_type(), reachable};
70	        // Upstream's own predicate, never a copy of it: the list of states that
71	        // count as printing has been got wrong here before.
72	        printer.activity = !machine->is_connected()         ? PrinterActivity::Offline :
73	                           machine->is_in_printing()        ? PrinterActivity::Printing :
74	                                                              PrinterActivity::Idle;
75	        if (machine->last_update_time.time_since_epoch().count() != 0)
76	            printer.observed_at_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
77	                                         machine->last_update_time.time_since_epoch())
78	                                         .count();
79	        printer.selected = machine == selected;
80	        read_reported_hardware(*machine, printer);
81	        result.push_back(std::move(printer));
82	    }
83	    std::sort(result.begin(), result.end(), [](const DiscoveredPrinter& a, const DiscoveredPrinter& b) {
84	        if (a.connected != b.connected) return a.connected > b.connected;
85	        if (a.name != b.name) return a.name < b.name;
86	        return a.stable_id < b.stable_id;
87	    });
88	    return result;
89	}
