330	bool FakeBambuAgent::reload_control_file()
331	{
332	    const auto path = boost::filesystem::path(control_file_path());
333	    if (!boost::filesystem::exists(path)) {
334	        std::lock_guard<std::mutex> lock(state_mutex);
335	        m_control_file_present = false;
336	        return false;
337	    }
338	
339	    std::int64_t mtime = 0;
340	    try {
341	        mtime = static_cast<std::int64_t>(boost::filesystem::last_write_time(path));
342	    } catch (...) {
343	        return false;
344	    }
345	
346	    {
347	        std::lock_guard<std::mutex> lock(state_mutex);
348	        if (m_control_file_present && mtime == m_control_mtime)
349	            return true;
350	    }
351	
352	    boost::nowide::ifstream in(path.string());
353	    if (!in)
354	        return false;
355	    std::ostringstream ss;
356	    ss << in.rdbuf();
357	
358	    FakeBambuStatusStep step;
359	    bool                offline = false;
360	    {
361	        std::lock_guard<std::mutex> lock(state_mutex);
362	        step = m_current;
363	    }
364	    if (!apply_control_json(ss.str(), step, offline)) {
365	        BOOST_LOG_TRIVIAL(warning) << "FakeBambuAgent: ignored invalid control file " << path.string();
366	        return false;
367	    }
368	
369	    {
370	        std::lock_guard<std::mutex> lock(state_mutex);
371	        m_current              = step;
372	        m_offline              = offline;
373	        m_control_file_present = true;
374	        m_control_mtime        = mtime;
375	    }
376	    return true;
377	}
